  const v = expr();
  const t = peek();
  if (t.t === 'rp') throw fail('this ")" has no matching "("', t.pos);
  if (t.t !== 'end') throw fail(`missing operator before ${describeToken(t)}`, t.pos, MULTIPLY_HINT);
